CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email VARCHAR(190) UNIQUE NOT NULL, password VARCHAR(255) NOT NULL, role ENUM('retailer','wholesaler','admin') NOT NULL, verified_at DATETIME NULL, active BOOLEAN NOT NULL DEFAULT 1, created_at DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE businesses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED UNIQUE NOT NULL, name VARCHAR(150) NOT NULL, type VARCHAR(100) NOT NULL DEFAULT '', contact VARCHAR(100) NOT NULL DEFAULT '', phone VARCHAR(40) NOT NULL DEFAULT '', address TEXT, city VARCHAR(100) NOT NULL DEFAULT '', description TEXT, status ENUM('pending','approved','suspended') NOT NULL DEFAULT 'pending', FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE addresses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, label VARCHAR(100) NOT NULL, address TEXT NOT NULL, city VARCHAR(100) NOT NULL, lat DECIMAL(10,7) NULL, lng DECIMAL(10,7) NULL, FOREIGN KEY(user_id) REFERENCES users(id), INDEX(user_id)) ENGINE=InnoDB;
CREATE TABLE fulfillment_settings (supplier_id BIGINT UNSIGNED PRIMARY KEY, pickup BOOLEAN NOT NULL DEFAULT 1, delivery BOOLEAN NOT NULL DEFAULT 1, delivery_fee INT UNSIGNED NULL, delivery_radius DECIMAL(8,2) NULL, lat DECIMAL(10,7) NULL, lng DECIMAL(10,7) NULL, pickup_instructions TEXT, lead_time VARCHAR(100) DEFAULT '1–3 business days', stripe_account VARCHAR(100) NULL, FOREIGN KEY(supplier_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) UNIQUE NOT NULL, slug VARCHAR(100) UNIQUE NOT NULL) ENGINE=InnoDB;
CREATE TABLE products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, category_id BIGINT UNSIGNED NOT NULL, name VARCHAR(150) NOT NULL, brand VARCHAR(100) NOT NULL, sku VARCHAR(100) UNIQUE NOT NULL, gtin VARCHAR(30) NULL, description TEXT, color VARCHAR(20) DEFAULT 'green', FOREIGN KEY(category_id) REFERENCES categories(id), INDEX(category_id), INDEX(name)) ENGINE=InnoDB;
CREATE TABLE offers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, supplier_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NOT NULL, pack_size DECIMAL(12,3) NOT NULL, unit VARCHAR(20) NOT NULL, price INT UNSIGNED NOT NULL, min_qty INT UNSIGNED NOT NULL DEFAULT 1, increment_qty INT UNSIGNED NOT NULL DEFAULT 1, stock INT UNSIGNED NOT NULL DEFAULT 0, archived BOOLEAN NOT NULL DEFAULT 0, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(supplier_id) REFERENCES users(id), FOREIGN KEY(product_id) REFERENCES products(id), INDEX(product_id,archived), INDEX(supplier_id), CHECK(pack_size>0), CHECK(min_qty>0), CHECK(increment_qty>0)) ENGINE=InnoDB;
CREATE TABLE offer_images (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, offer_id BIGINT UNSIGNED NOT NULL, filename VARCHAR(100) NOT NULL, mime VARCHAR(30) NOT NULL, FOREIGN KEY(offer_id) REFERENCES offers(id)) ENGINE=InnoDB;
CREATE TABLE price_tiers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, offer_id BIGINT UNSIGNED NOT NULL, min_qty INT UNSIGNED NOT NULL, price INT UNSIGNED NOT NULL, FOREIGN KEY(offer_id) REFERENCES offers(id), UNIQUE(offer_id,min_qty)) ENGINE=InnoDB;
CREATE TABLE external_sources (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) UNIQUE NOT NULL, mode ENUM('import','demo') NOT NULL DEFAULT 'import') ENGINE=InnoDB;
CREATE TABLE external_offers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, source_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NOT NULL, source_url VARCHAR(1000) NULL, price INT UNSIGNED NOT NULL, currency CHAR(3) NOT NULL, pack_size DECIMAL(12,3) NOT NULL, unit VARCHAR(20) NOT NULL, delivery_fee INT UNSIGNED NULL, updated_at DATETIME NOT NULL, FOREIGN KEY(source_id) REFERENCES external_sources(id), FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB;
CREATE TABLE carts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, retailer_id BIGINT UNSIGNED UNIQUE NOT NULL, FOREIGN KEY(retailer_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE cart_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, cart_id BIGINT UNSIGNED NOT NULL, offer_id BIGINT UNSIGNED NOT NULL, quantity INT UNSIGNED NOT NULL, FOREIGN KEY(cart_id) REFERENCES carts(id), FOREIGN KEY(offer_id) REFERENCES offers(id), UNIQUE(cart_id,offer_id)) ENGINE=InnoDB;
CREATE TABLE checkouts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, retailer_id BIGINT UNSIGNED NOT NULL, currency CHAR(3) NOT NULL, status ENUM('pending','paid','demo_paid','failed','expired','cancelled','refunded','partially_refunded') DEFAULT 'pending', mode ENUM('demo','stripe') NOT NULL, subtotal INT UNSIGNED NOT NULL, delivery INT UNSIGNED NOT NULL, tax INT UNSIGNED NOT NULL, fee INT UNSIGNED NOT NULL, total INT UNSIGNED NOT NULL, fee_bps INT UNSIGNED NOT NULL, tax_bps INT UNSIGNED NOT NULL, address_snapshot JSON NULL, request_key VARCHAR(64) UNIQUE NOT NULL, expires_at DATETIME NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(retailer_id) REFERENCES users(id), INDEX(status,expires_at)) ENGINE=InnoDB;
CREATE TABLE supplier_orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, checkout_id BIGINT UNSIGNED NOT NULL, supplier_id BIGINT UNSIGNED NOT NULL, supplier_snapshot JSON NOT NULL, fulfillment ENUM('delivery','pickup') NOT NULL, instructions TEXT, status ENUM('pending','accepted','preparing','ready_for_pickup','shipped','delivered','cancelled') DEFAULT 'pending', subtotal INT UNSIGNED NOT NULL, delivery INT UNSIGNED NOT NULL, tax INT UNSIGNED NOT NULL, fee INT UNSIGNED NOT NULL, total INT UNSIGNED NOT NULL, notes TEXT, FOREIGN KEY(checkout_id) REFERENCES checkouts(id), FOREIGN KEY(supplier_id) REFERENCES users(id), INDEX(supplier_id,status)) ENGINE=InnoDB;
CREATE TABLE order_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, offer_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NOT NULL, category_id BIGINT UNSIGNED NOT NULL, name VARCHAR(150) NOT NULL, sku VARCHAR(100) NOT NULL, pack_size DECIMAL(12,3) NOT NULL, unit VARCHAR(20) NOT NULL, quantity INT UNSIGNED NOT NULL, price INT UNSIGNED NOT NULL, total INT UNSIGNED NOT NULL, FOREIGN KEY(order_id) REFERENCES supplier_orders(id), FOREIGN KEY(offer_id) REFERENCES offers(id), FOREIGN KEY(product_id) REFERENCES products(id), FOREIGN KEY(category_id) REFERENCES categories(id)) ENGINE=InnoDB;
CREATE TABLE order_status_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, actor_id BIGINT UNSIGNED NULL, status VARCHAR(40) NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES supplier_orders(id), FOREIGN KEY(actor_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, checkout_id BIGINT UNSIGNED UNIQUE NOT NULL, provider VARCHAR(20) NOT NULL, provider_session VARCHAR(190) UNIQUE NULL, payment_intent VARCHAR(190) UNIQUE NULL, status VARCHAR(30) NOT NULL DEFAULT 'pending', amount INT UNSIGNED NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(checkout_id) REFERENCES checkouts(id)) ENGINE=InnoDB;
CREATE TABLE webhook_events (event_id VARCHAR(190) PRIMARY KEY, type VARCHAR(100) NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE refunds (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED UNIQUE NOT NULL, amount INT UNSIGNED NOT NULL, merchandise INT UNSIGNED NOT NULL, delivery INT UNSIGNED NOT NULL, tax INT UNSIGNED NOT NULL, fee INT UNSIGNED NOT NULL, provider_ref VARCHAR(190) NULL, status VARCHAR(30) NOT NULL DEFAULT 'pending', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES supplier_orders(id)) ENGINE=InnoDB;
CREATE TABLE payouts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED UNIQUE NOT NULL, amount INT UNSIGNED NOT NULL, provider_ref VARCHAR(190) NULL, status VARCHAR(30) DEFAULT 'pending', FOREIGN KEY(order_id) REFERENCES supplier_orders(id)) ENGINE=InnoDB;
CREATE TABLE inventory_reservations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, checkout_id BIGINT UNSIGNED NOT NULL, offer_id BIGINT UNSIGNED NOT NULL, quantity INT UNSIGNED NOT NULL, status ENUM('reserved','consumed','released') DEFAULT 'reserved', expires_at DATETIME NOT NULL, FOREIGN KEY(checkout_id) REFERENCES checkouts(id), FOREIGN KEY(offer_id) REFERENCES offers(id), INDEX(status,expires_at), UNIQUE(checkout_id,offer_id)) ENGINE=InnoDB;
CREATE TABLE conversations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id BIGINT UNSIGNED NULL, order_id BIGINT UNSIGNED NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(product_id) REFERENCES products(id), FOREIGN KEY(order_id) REFERENCES supplier_orders(id)) ENGINE=InnoDB;
CREATE TABLE conversation_participants (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, conversation_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, last_read_at DATETIME NULL, FOREIGN KEY(conversation_id) REFERENCES conversations(id), FOREIGN KEY(user_id) REFERENCES users(id), UNIQUE(conversation_id,user_id)) ENGINE=InnoDB;
CREATE TABLE messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, conversation_id BIGINT UNSIGNED NOT NULL, sender_id BIGINT UNSIGNED NOT NULL, body TEXT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(conversation_id) REFERENCES conversations(id), FOREIGN KEY(sender_id) REFERENCES users(id), INDEX(conversation_id,id)) ENGINE=InnoDB;
CREATE TABLE tokens (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, kind ENUM('reset','verify') NOT NULL, token_hash CHAR(64) UNIQUE NOT NULL, expires_at DATETIME NOT NULL, used_at DATETIME NULL, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE rate_limits (bucket CHAR(64) PRIMARY KEY, attempts INT UNSIGNED DEFAULT 1, started_at DATETIME NOT NULL) ENGINE=InnoDB;
CREATE TABLE settings (name VARCHAR(100) PRIMARY KEY, value TEXT NOT NULL) ENGINE=InnoDB;
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, actor_id BIGINT UNSIGNED NOT NULL, action VARCHAR(100) NOT NULL, entity VARCHAR(190) NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(actor_id) REFERENCES users(id)) ENGINE=InnoDB;
